MagickBooleanType DecodeDXT3Image(Image *image, DDSInfo *dds_info, ExceptionInfo *exception)
{
    if (!image || !dds_info)
        return MagickFalse;

    register PixelIterator *iterator;
    register PixelWand *pixel;
    register ssize_t x;
    register ssize_t y;
    size_t width, height;
    unsigned char *dxt3_data;
    size_t dxt3_data_size;
    MagickBooleanType status;

    width = dds_info->width;
    height = dds_info->height;
    dxt3_data_size = (width + 3) / 4 * ((height + 3) / 4) * 16;
    dxt3_data = AcquireQuantumMemory(dxt3_data_size, sizeof(*dxt3_data));
    if (!dxt3_data)
        return MagickFalse;

    // Skip mipmaps
    if (dds_info->mipmap_count > 1)
        SkipMipMaps(dds_info);

    // Iterate over each 4x4 block
    for (y = 0; y < height; y += 4)
    {
        for (x = 0; x < width; x += 4)
        {
            unsigned short color_codes[4];
            unsigned char alpha_values[16];

            // Read alpha values and color codes
            if (ReadDXT3BlockAlpha(alpha_values, dxt3_data, width, x, y, dds_info) == MagickFalse ||
                ReadDXT3BlockColor(color_codes, dxt3_data, width, x, y, dds_info) == MagickFalse)
            {
                status = MagickFalse;
                goto cleanup;
            }

            // Decode 4x4 block
            for (ssize_t block_y = 0; block_y < 4; block_y++)
            {
                for (ssize_t block_x = 0; block_x < 4; block_x++)
                {
                    ssize_t px = x + block_x;
                    ssize_t py = y + block_y;

                    if (px >= (ssize_t)width || py >= (ssize_t)height)
                        continue;

                    unsigned char alpha = alpha_values[block_y * 4 + block_x];
                    unsigned short color_index = color_codes[block_y * 4 + block_x];
                    PixelInfo pixel_color;

                    // Set pixel color using the decoded color codes and alpha
                    if (GetPixelColor(&pixel_color, px, py, image, exception) == MagickFalse)
                    {
                        status = MagickFalse;
                        goto cleanup;
                    }

                    pixel_color.alpha = alpha;

                    if (SetPixelColor(pixel_color, px, py, image, exception) == MagickFalse)
                    {
                        status = MagickFalse;
                        goto cleanup;
                    }
                }
            }
        }
    }

    status = MagickTrue;

cleanup:
    dxt3_data = RelinquishMagickMemory(dxt3_data);
    return status;
}

MagickBooleanType DecodeDXT3Image(Image *image, DDSInfo *dds_info, ExceptionInfo *exception)
{
  register PixelGeometry *p = image->pixels;
  const size_t width = dds_info->width;
  const size_t height = dds_info->height;
  const size_t width_in_blocks = (width + 3) / 4;
  const size_t height_in_blocks = (height + 3) / 4;
  size_t y;

  for (y = 0; y < height_in_blocks; y++)
  {
    size_t x;
    for (x = 0; x < width_in_blocks; x++)
    {
      unsigned char alpha[16];
      unsigned short color_codes[4];
      unsigned char *block_data = dds_info->data + (y * width_in_blocks + x) * 16;
      size_t i;

      /* Read the alpha values */
      for (i = 0; i < 16; i++)
      {
        alpha[i] = *(block_data + i);
      }

      /* Read the color codes */
      for (i = 0; i < 4; i++)
      {
        color_codes[i] = *(unsigned short*)(block_data + 8 + (i * 2));
      }

      /* Process the 4x4 pixel block */
      for (i = 0; i < 16; i++)
      {
        size_t row = (i / 4);
        size_t col = (i % 4);
        unsigned char alpha_value = alpha[i];
        unsigned short color_code = color_codes[alpha_value];
        PixelGeometry *pixel = p + (y * 4 + row) * image->columns + (x * 4 + col);

        pixel->red = (Quantum) ((color_code >> 11) & 0x1F) * 8;
        pixel->green = (Quantum) ((color_code >> 5) & 0x3F) * 4;
        pixel->blue = (Quantum) (color_code & 0x1F) * 8;
        pixel->alpha = (Quantum) alpha_value;
      }
    }
  }

  /* Skip mipmaps */
  dds_info->data += width_in_blocks * height_in_blocks * 16;

  return MagickTrue;
}

MagickBooleanType DecodeDXT3Image(Image *image, DDSInfo *dds_info, ExceptionInfo *exception)
{
    size_t block_width, block_height, block_count, i, j, x, y;
    unsigned int alpha_table[4];
    unsigned short color_table[4];
    unsigned char alpha_data[16];
    unsigned short color_data[2];
    unsigned char *pixels;
    MagickBooleanType result;

    block_width = (dds_info->width + 3) / 4;
    block_height = (dds_info->height + 3) / 4;
    block_count = block_width * block_height;

    pixels = image->pixels;

    for (i = 0; i < block_height; i++)
    {
        for (j = 0; j < block_width; j++)
        {
            for (y = 0; y < 4; y++)
            {
                for (x = 0; x < 4; x++)
                {
                    size_t index = i * block_width * 4 * 8 + j * 8 + y * block_width * 8 + x * 2;
                    size_t pixel_index = (i * 4 + y) * image->columns + j * 4 + x;

                    if (pixel_index >= image->columns * image->rows)
                        continue;

                    if (index + 1 >= dds_info->data_size)
                        return MagickFalse;

                    color_data[0] = ReadPSDShort(dds_info->data + index);
                    color_data[1] = ReadPSDShort(dds_info->data + index + 2);

                    alpha_table[0] = (dds_info->data[index + 4] << 8) | dds_info->data[index + 5];
                    alpha_table[1] = (dds_info->data[index + 6] << 8) | dds_info->data[index + 7];

                    for (int k = 0; k < 16; k++)
                    {
                        alpha_data[k] = alpha_table[(k >> 4) & 1];
                    }

                    for (int k = 0; k < 16; k++)
                    {
                        unsigned char alpha_index = (k & 15) >> 2;
                        alpha_data[alpha_index] = alpha_table[k & 1];
                    }

                    for (int k = 0; k < 16; k++)
                    {
                        unsigned char alpha_index = (k & 15) >> 2;
                        pixels[pixel_index * 4 + alpha_index] = alpha_data[alpha_index];
                    }

                    if (color_data[0] > color_data[1])
                    {
                        color_table[0] = color_data[0];
                        color_table[1] = color_data[1];
                        color_table[2] = ((color_data[0] & 0x07E0) >> 11) * 32 + ((color_data[1] & 0x07E0) >> 11) * 32;
                        color_table[3] = ((color_data[0] & 0x001F) >> 11) * 32 + ((color_data[1] & 0x001F) >> 11) * 32;
                    }
                    else
                    {
                        color_table[0] = color_data[0];
                        color_table[1] = color_data[1];
                        color_table[2] = ((color_data[0] & 0x07E0) >> 11) * 32 + ((color_data[1] & 0x07E0) >> 11) * 32;
                        color_table[3] = ((color_data[0] & 0x001F) >> 11) * 32 + ((color_data[1] & 0x001F) >> 11) * 32;
                    }

                    for (int k = 0; k < 16; k++)
                    {
                        unsigned char color_index = (k & 15) >> 2;
                        pixels[pixel_index * 4 + color_index] = color_table[color_index];
                    }
                }
            }

            result = SkipMipmaps(dds_info);
            if (result == MagickFalse)
                return MagickFalse;
        }
    }

    return MagickTrue;
}

MagickBooleanType DecodeDXT3(Image *image, DDSInfo *dds_info, ExceptionInfo *exception) {
    ssize_t
        x,
        y,
        block_x,
        block_y;

    unsigned char
        *dxt_data = (unsigned char *) dds_info->data;

    MagickBooleanType
        status = MagickTrue;

    if ((image->columns & 3) != 0 || (image->rows & 3) != 0)
        status = MagickFalse;

    for (block_y = 0; block_y < image->rows; block_y += 4) {
        for (block_x = 0; block_x < image->columns; block_x += 4) {
            for (y = 0; y < 4 && (block_y + y) < image->rows; y++) {
                for (x = 0; x < 4 && (block_x + x) < image->columns; x++) {
                    unsigned int alpha_index = (block_y + y) * image->columns + (block_x + x);
                    unsigned int alpha_offset = (alpha_index / 8) * 8;
                    unsigned int alpha_byte = dxt_data[alpha_offset + (y * 4 + x) / 2];
                    unsigned int alpha_bit = (y * 4 + x) % 2;

                    unsigned char alpha = (alpha_byte >> (4 * alpha_bit)) & 0x0F;

                    unsigned int color_offset = dxt_data[alpha_offset + 8 + (y * 4 + x) / 8];
                    unsigned int color_mask = (0x001F & (color_offset >> 3)) << 3;
                    unsigned int red = (color_mask >> 8) & 0xF8;
                    unsigned int green = (color_mask >> 3) & 0xF8;
                    unsigned int blue = (color_mask << 3) & 0xF8;

                    GetPixelInfo(image, exception);
                    image->pixels[alpha_index] = (PixelPacket) { red, green, blue, alpha };
                }
            }

            dxt_data += 8 + (4 * 4) / 8;
        }
    }

    if (!SkipMipmaps(dxt_data, dds_info)) {
        status = MagickFalse;
    }

    return status;
}

MagickBooleanType DecodeDXT3(Image *image, const DDSInfo *dds_info, ExceptionInfo *exception) {
  MagickBooleanType status = MagickTrue;
  size_t width = dds_info->width;
  size_t height = dds_info->height;
  size_t row, col, x, y, alpha_index;
  Quantum *q;
  register ssize_t i;
  unsigned char alpha_block[16];
  unsigned short alpha_value;
  unsigned int alpha_index_table[16];
  unsigned int alpha_code;
  unsigned int color_code;
  unsigned int color0;
  unsigned int color1;
  unsigned int r0, g0, b0;
  unsigned int r1, g1, b1;
  unsigned int color_table[4];

  for (y = 0; y < height; y += 4) {
    for (x = 0; x < width; x += 4) {
      /* Read alpha block (16 bytes) */
      for (i = 0; i < 16; i++) {
        alpha_block[i] = 0;
        if (ReadBlobByte(image) == EOF) {
          status = MagickFalse;
          break;
        }
        alpha_block[i] = (unsigned char) ReadBlobByte(image);
      }
      if (!status)
        break;

      alpha_code = 0;
      for (i = 0; i < 2; i++) {
        alpha_code = (alpha_code << 8) + ReadBlobByte(image);
      }

      for (i = 0; i < 16; i++) {
        alpha_index_table[i] = (alpha_code >> (2 * i)) & 0x03;
      }

      for (i = 0; i < 16; i++) {
        alpha_value = alpha_block[alpha_index_table[i]];
        alpha_index_table[i] = alpha_value;
      }

      /* Read color block (8 bytes) */
      color0 = (unsigned int) ReadBlobShort(image);
      color1 = (unsigned int) ReadBlobShort(image);

      r0 = ((color0 >> 11) & 0x1F) * 8;
      g0 = ((color0 >> 5) & 0x3F) * 4;
      b0 = ((color0 >> 0) & 0x1F) * 8;

      r1 = ((color1 >> 11) & 0x1F) * 8;
      g1 = ((color1 >> 5) & 0x3F) * 4;
      b1 = ((color1 >> 0) & 0x1F) * 8;

      color_table[0] = (r0 << 16) | (g0 << 8) | b0;
      color_table[1] = (r1 << 16) | (g1 << 8) | b1;
      color_table[2] = ( ((6 * r0) + (1 * r1)) ) / 7;
      color_table[3] = ( ((1 * r0) + (6 * r1)) ) / 7;

      for (row = 0; row < 4; row++) {
        for (col = 0; col < 4; col++) {
          i = (row * 4 + col) * 2;
          color_code = (unsigned int) ReadBlobShort(image);

          if (color_code >= 4) {
            continue;
          }

          q = GetAuthenticPixels(image, x + col, y + row, 1, 1, exception);
          if (q == (Quantum *) NULL)
            continue;

          SetPixelRed(image, color_table[color_code] >> 16, q);
          SetPixelGreen(image, color_table[color_code] >> 8, q);
          SetPixelBlue(image, color_table[color_code] >> 0, q);
          SetPixelAlpha(image, alpha_index_table[row * 4 + col], q);

          if (!SyncAuthenticPixels(image, exception))
            status = MagickFalse;
        }
      }
    }
  }

  /* Skip mipmaps */
  if (!SkipMipmaps(image, dds_info, exception))
    status = MagickFalse;

  return status;
}
